-- Official SAT Practice Tests (paper versions), generated by supabase/content/sat/build_sat.py. Do not edit by hand.
-- Run after migration 20261121000001_student_produced_responses.sql. Safe to re-run: existing exams are skipped.

select s.id, 'topic', v.name, v.ord from (values
  ('sat-math', 'Algebra', 1),
  ('sat-math', 'Advanced Math', 2),
  ('sat-math', 'Problem-Solving and Data Analysis', 3),
  ('sat-math', 'Geometry and Trigonometry', 4),
  ('sat-english', 'Craft and Structure', 1),
  ('sat-english', 'Information and Ideas', 2),
  ('sat-english', 'Standard English Conventions', 3),
  ('sat-english', 'Expression of Ideas', 4)
) as v(code, name, ord) join public.subjects s on s.code = v.code
on conflict (subject_id, kind, name) do nothing;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 4: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-4-reading-and-writing') then
    raise notice 'skipping sat-practice-test-4-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-4-reading-and-writing', 'SAT Practice Test 4: Reading and Writing', 'Official SAT Practice Test 4 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 208, '[[200, 200], [200, 200], [200, 200], [200, 200], [200, 200], [200, 200], [200, 200], [200, 210], [200, 220], [210, 230], [230, 250], [240, 260], [250, 270], [260, 280], [280, 300], [290, 310], [320, 340], [340, 360], [350, 370], [360, 380], [370, 390], [370, 390], [380, 400], [390, 410], [400, 420], [410, 430], [420, 440], [420, 440], [430, 450], [440, 460], [450, 470], [460, 480], [460, 480], [470, 490], [480, 500], [490, 510], [490, 510], [500, 520], [510, 530], [520, 540], [530, 550], [540, 560], [540, 560], [550, 570], [560, 580], [570, 590], [580, 600], [590, 610], [590, 610], [600, 620], [610, 630], [620, 640], [630, 650], [630, 650], [640, 660], [650, 670], [660, 680], [670, 690], [680, 700], [690, 710], [700, 720], [710, 730], [720, 740], [730, 750], [750, 770], [770, 790], [790, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of the OSIRIS-REx spacecraft’s contact with the asteroid 101955 Bennu. In this context, “collected” means acquired and took away. The text indicates that although the boulders on the asteroid’s surface caused some unforeseen problems, OSIRIS-REx was able to gather a sample to return to Earth. This context suggests that OSIRIS-REx successfully collected a sample of 101955 Bennu."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context “attached” means connected or affixed. The text indicates that OSIRIS-REx gathered pieces of 101955 Bennu to bring to Earth; it doesn’t suggest that the spacecraft attached anything to the asteroid. Choice C is incorrect because in this context “followed” means tracked or traveled behind and the text discusses OSIRIS-REx’s brief encounter with 101955 Bennu during which the spacecraft gathered a sample to bring to Earth. The text doesn’t suggest that the spacecraft tracked the sample, and it’s not clear what it would mean for the spacecraft to travel behind the sample it collected."}, {"type": "paragraph", "text": "Choice D is incorrect because in this context “replaced” means put back or returned. The text indicates that OSIRIS-REx gathered pieces of 101955 Bennu to bring to Earth but doesn’t suggest that anything was returned to the asteroid."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the Moon’s surface. In this context, “reflect” means show or make apparent. The text states that because the surface of the Moon was softer when the Moon was still forming than it is now, early asteroid and meteoroid impacts “would have left less of an impression” and, as a result, evidence of them may no longer exist. This context supports the idea that the surface of the Moon may not accurately show signs of early impact events."}, {"type": "paragraph", "text": "Choice B is incorrect because it wouldn’t make sense to say that the surface of the Moon may not accurately “receive,” or acquire or experience, early impacts from asteroids or meteoroids. The text indicates that the impacts have already occurred, and it isn’t clear how the Moon’s surface could be accurate or inaccurate in experiencing them. Choice C is incorrect because it wouldn’t make sense to say that the surface of the Moon may not accurately “evaluate,” or determine the significance or condition of, early impacts from asteroids or meteoroids, since that would suggest that it’s possible for the Moon’s surface to make a decision of any kind. Choice D is incorrect. In this context, “mimic” would mean to deliberately simulate or closely imitate something. It wouldn’t make sense to say that the surface of the Moon may not accurately mimic early asteroid and meteoroid impacts, since that would suggest that it’s possible for the Moon to deliberately imitate something."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion about handedness in animals. As used in this context, “recognizable” means apparent or identifiable. The text indicates that handedness is “easy to observe in humans,” but that animal-behavior researchers use special tasks to determine handedness in other animals. This context and the use of “less” before the blank indicate that compared with handedness in humans, handedness in other animals is less recognizable."}, {"type": "paragraph", "text": "Choice B is incorrect because there’s nothing in the text to suggest that handedness is less “intriguing,” or fascinating, in nonhuman animals than it is in humans. The text focuses on how easy it is to observe handedness in humans as compared with other animals; the text doesn’t suggest that handedness is more fascinating in humans. Choice C is incorrect because there’s nothing in the text to suggest that handedness is less “significant,” or important or meaningful, in nonhuman animals than it is in humans. The text focuses on how easy it is to observe handedness in humans as compared with other animals; the text doesn’t suggest that handedness is more significant in humans. Choice D is incorrect because “useful,” or functional or helpful, wouldn’t make sense in context. The text focuses on the ease with which researchers can determine whether an animal or person is right- or left-handed, not on how useful handedness in nonhuman animals is compared with handedness in humans."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of the influences on Banisadr’s work. As used in this context, “unimportant” means trivial or lacking value. “It is by no means” establishes that the word that goes in the blank is contradicted by other information; the material that follows “indeed” later in that sentence provides the contradicting information—namely, that Banisadr himself cites Bosch as an inspiration. In other words, the sentence indicates that Bosch’s influence on Banisadr is significant, and thus recognizing that influence is by no means unimportant."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make sense to say that recognizing Bosch’s influence on Banisadr isn’t “substantial,” or meaningful. The text states that Banisadr himself cites Bosch as an influence. Choice B is incorrect because it wouldn’t make sense to say that it isn’t “satisfying,” or pleasing, to recognize Bosch’s influence on Banisadr. The text states that Banisadr himself cites Bosch as an influence. Choice D is incorrect because it wouldn’t make sense to say that recognizing Bosch’s influence on Banisadr isn’t “appropriate,” or suitable. The text indicates that Banisadr himself notes that Bosch’s work has had an effect on him."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes the main purpose of the text. The text begins by stating that the new picture “failed to fit in” with the other items that the shop owner has. The text goes on to illustrate that point by describing the other pictures the shop owner has, indicating that the shop owner is fuming because he doesn’t think the new picture belongs in the store. In the second paragraph, however, the text indicates that the shop owner is “secretly proud of his acquisition.” The main purpose of the text is thus to reveal the shop owner’s conflicted feelings about the new picture."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t suggest that the shop owner resents the young man who sold him the new picture; in fact, the text gives no indication of the owner’s feelings about the young man at all. Choice C is incorrect. Although the text indicates that the new picture is different from the other items in the shop, there’s no suggestion that the shop owner prizes either the new picture or the pictures of the city, pets, and landscapes more than he prizes any other items. Choice D is incorrect because the text doesn’t describe what the new picture looks like; rather, the text identifies some of the other kinds of images that the shop owner has and states that they’re different from the new picture without explaining how they’re different."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes the overall structure of the text. First, the speaker describes observing a “most beautiful” sight: a tree (“black cypress”) standing out from the golden sky behind it, looking like a person’s finger “pointing upwards” and appearing “sensitive” and “exquisite.” Then the speaker wonders about the image’s meaning, asking why the finger is black and why it’s pointing upward. Thus, the text moves from the speaker’s description of a distinctive sight in nature to her pondering about what meaning to attribute to that sight."}, {"type": "paragraph", "text": "Choice A is incorrect because the speaker assesses a natural sight—a “black cypress” tree standing “against a gold, gold sky” like a pointed finger—but doesn’t question the accuracy of her own assessment. Although she wonders why the finger, which is really a tree, is black and why it’s pointing, the speaker doesn’t suggest that her belief that the tree resembles a finger is wrong. Choice C is incorrect. Although the speaker describes seeing a “black cypress” tree standing “against a gold, gold sky” like a pointed finger, she wonders about that natural image (asking why the finger, which is really a tree, is black and why it’s pointing) and doesn’t give any indication that any people are present in the scene. Choice D is incorrect. Although the speaker examines and wonders about one thing in her surroundings—a “black cypress” tree standing “against a gold, gold sky” like a pointed finger—she doesn’t address her own emotional state or consider how it’s affected by her surroundings."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it best describes the overall structure of the text. The speaker begins by stating that he has heard that others are accusing him of seeking to destroy institutions. The speaker then addresses this criticism by stating that he is “neither for nor against institutions.” Instead, the speaker states that his ultimate goal is to instill “the institution of the dear love of comrades” everywhere in the country. Therefore, the overall structure of the text is best described as an address of criticism followed by an announcement of a grand ambition."}, {"type": "paragraph", "text": "Choice A is incorrect. While the speaker does address an opinion of him that he believes to be untrue, he doesn’t indicate that this attitude has become increasingly prevalent. The speaker also concludes by explaining his goal for the future rather than his current worldview. Choice B is incorrect because the text doesn’t portray the speaker as isolated or regretful, and the speaker gestures toward a hope for societal change but doesn’t offer an explicit prediction that it will happen. Choice C is incorrect because the speaker addresses a criticism of him that he believes to be false; he doesn’t admit any personal shortcomings. Moreover, the speaker concludes by stating a goal he has rather than showcasing his achievements."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the third sentence in the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes the function of the third sentence within the overall structure of the text. The third sentence makes a generalization, asserting that evolutionary links between predators and prey can persist across great expanses of time and distance. This generalization is exemplified by the text’s discussion of the relationship between mimosa trees and B. terrenus beetles. When mimosa trees were introduced to North America in 1785, no B. terrenus beetles were present, so the relationship between the trees and the beetles that exists in their native East Asia was disrupted. When the beetles were introduced to North America more than 200 years later, however, they quickly attacked mimosa trees, illustrating the generalization that links between predators and prey “can persist across centuries and continents.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the third sentence doesn’t indicate that Chang and colleagues were investigating any particular hypothesis. According to the text, Chang and colleagues were simply monitoring mimosa trees when the beetles happened to be introduced to the area. Choice C is incorrect because the third sentence offers a generalization about the relationship between predators and prey, not an explanation for the findings of Chang and colleagues that differs from an explanation presented elsewhere in the text. Choice D is incorrect because the third sentence doesn’t discuss any particular species (either the species mentioned elsewhere in the text or any other) and doesn’t help explain why species spread to new locations."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would Graeber and Wengrow (Text 2) most likely respond to the “conventional wisdom” presented in Text 1?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it describes the most likely way that Graeber and Wengrow (Text 2) would respond to the “conventional wisdom” presented in Text 1. According to Text 1, the conventional wisdom about human social systems is that they developed through stages, beginning with hunter-gatherer bands, then moving to clan associations, then chiefdoms, and finally arriving at states with bureaucratic structures. Text 2 indicates that Graeber and Wengrow believe that human social systems have been flexible, shifting between different types of structures, including both hierarchical and collective systems, and that these shifts may have even occurred seasonally. This suggests that Graeber and Wengrow would dispute the idea that developments in social structures have followed a linear progression through distinct stages."}, {"type": "paragraph", "text": "Choice A is incorrect because nothing in Text 2 suggests that Graeber and Wengrow believe that decentralized collective societies are more significant than hierarchical systems. Text 2 is focused on Graeber and Wengrow’s view that humans have flexibly shifted among various social structures, not on the importance of particular structures relative to others. Choice C is incorrect because Text 2 doesn’t include any information suggesting that Graeber and Wengrow believe that hierarchies didn’t emerge until after the rise of agriculture. In fact, Text 2 indicates that Graeber and Wengrow cite evidence suggesting that some hunter-gatherer groups formed social structures with hierarchical elements (“communities that included esteemed individuals”) 50,000 years ago, long before the rise of agriculture, which Text 1 says occurred around 12,000 years ago."}, {"type": "paragraph", "text": "Choice D is incorrect because there’s no information in Text 2 suggesting that Graeber and Wengrow would challenge the assumption that groupings of hunter- gatherers were among the earliest forms of social structure. Although Text 1 does indicate that hunter-gatherer groups are assumed to be the earliest human social system, Text 2 says only that Graeber and Wengrow believe that some hunter- gatherer groups made use of different social structures at different times. Text 2 doesn’t imply that Graeber and Wengrow doubt that hunter-gatherer groups preceded most other social structures."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately states the main idea of the text. The text describes Mary’s activities in an overgrown hidden garden, saying that she was “very much absorbed” and was “only becoming more pleased with her work every hour” rather than getting tired of it. She also thinks of garden activities as a “fascinating sort of play.” Thus, the main idea of the text is that Mary feels very satisfied when taking care of the garden."}, {"type": "paragraph", "text": "Choice A is incorrect because the text never makes any mention of Mary’s chores. Choice B is incorrect because the text indicates that Mary finds pulling up weeds to be fascinating, not boring. Choice C is incorrect because Mary thinks of garden activities in and of themselves as play, not as something necessary to do to create a space to play."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the text, in what way is the human mind like a flower?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a description of how the human mind is like a flower that is directly supported by the text. The text compares the needs of a “fragile and lovely flower” to those of the speaker’s “tender mind”: both need to be fed if they’re going to survive. Without such feeding, they’ll “beginneth straightway to languish,” or weaken. Thus, the text suggests that the human mind is like a flower in that they both need proper nourishment in order to thrive."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t address the passage of time or describe either the human mind or a flower as becoming increasingly vigorous."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t suggest that human minds or flowers draw strength from changes in weather. The references to rain in the text pertain to a flower’s need for water rather than the general effects of changing weather. Choice D is incorrect because the text doesn’t suggest that the human mind or a flower will persist regardless of challenging circumstances. In fact, the text indicates that they’ll both languish right away if not given what they need."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately states the main idea of the text. After establishing that Buck views most people “as nothing,” the text explains that Buck won’t acknowledge people other than Thornton unless they appear friendly toward Thornton, and even then he’s only reluctantly accepting. Thus, the text focuses on the idea that Thornton has a special status in Buck’s mind, with Buck holding him in higher regard than other people."}, {"type": "paragraph", "text": "Choice A is incorrect because the text conveys that Buck isn’t social with people other than Thornton but doesn’t address Buck’s life or temperament before he lived with Thornton. Choice B is incorrect because the text conveys that Buck doesn’t really care about people other than Thornton and is aloof toward them. However, there’s no indication that Buck mistrusts and avoids people generally; indeed, he accepts Thornton, who is a human. Choice C is incorrect because the text refers to random travelers praising and petting Buck and Thornton’s partners giving Buck favors, but there’s no indication that any of these people are Thornton’s friends or that they have a particular fondness for Buck."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it uses data from the graph to accurately complete the text. The graph shows the number of organic farms located in each of six US states in 2016: between 2,600 and 2,800 in California; between 1,200 and 1,400 in Wisconsin; between 1,000 and 1,200 in New York; approximately 800 in Pennsylvania; and between 600 and 800 in both Iowa and Washington. The last sentence of the text provides information about the number of organic farms in 2016, first describing the number in California. The best completion of the sentence is the choice that accurately describes the number of organic farms in 2016 in another state, which the assertion that Washington had between 600 and 800 organic farms provides."}, {"type": "paragraph", "text": "Choice B is incorrect because it doesn’t accurately reflect the data from the graph. The graph indicates that there were between 1,000 and 1,200 organic farms in New York, not fewer than 800 organic farms. Choice C is incorrect because it doesn’t accurately reflect the data from the graph. While the graph indicates that there were between 1,200 and 1,400 organic farms in Wisconsin in 2016, there were only between 600 and 800 in Iowa. Choice D is incorrect because it doesn’t accurately reflect the data from the graph. The graph indicates that in 2016 there were approximately 800 organic farms in Pennsylvania, not more than 1,200."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support Gómez-Bahamón and her team’s hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents a finding that, if true, would most directly support Gómez-Bahamón and her team’s hypothesis about fork-tailed flycatchers. The text indicates that although two subspecies of the birds live in the same region, the tail feathers of the migrating males make a higher-pitched sound than the tail feathers of the nonmigrating males do. Gómez-Bahamón and her team hypothesize that female fork-tailed flycatchers are attracted to the particular sound made by the tail feathers of males of their own subspecies, which will bring about additional “genetic and anatomical divergence” between the two subspecies. If it were found that the pitch generated by the tail feathers of migrating males is getting higher over successive generations, it would indicate that the shape of the migrating subspecies’ tail feathers is diverging further from that of the nonmigrating subspecies. And if females continue to prefer the sounds of the males of their own subspecies, the females of the migrating subspecies will become acclimated to increasingly higher pitches over subsequent generations, causing further divergence between the subspecies. Thus, if it were found that migrating males’ tail feathers were producing higher pitches over time, that would support the researchers’ hypothesis."}, {"type": "paragraph", "text": "Choice A is incorrect because the researchers’ hypothesis is that female flycatchers prefer the sounds produced by the tail feathers of males of their own subspecies, which will lead to further divergence between the two subspecies. This finding is about the shape of wing feathers and how that affects long- distance flight, whereas the hypothesis is about the shape of tail feathers and how that relates to female mate preference. Choice C is incorrect because the researchers’ hypothesis is that female flycatchers prefer the sounds produced by the tail feathers of males of their own subspecies, which will lead to further divergence between the two subspecies. This finding focuses on how the tail feather sounds communicate different messages, which doesn’t address differences between the subspecies or female preferences. Choice D is incorrect because the researchers’ hypothesis is that female flycatchers prefer the sounds produced by the tail feathers of males of their own subspecies, which will lead to further divergence between the two subspecies. The finding that breeding habits haven’t changed for either subspecies does not, by itself, suggest anything about female preferences or divergence between the two subspecies."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the example?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most effectively completes the example regarding the ablation rate of iron. The table shows the ablation rates for three elements—iron, potassium, and sodium—found in cosmic dust that comes from one of four sources. The text says that the ablation rate for a given element in slower-moving SPC or AST dust was lower than the ablation rate for that same element in faster-moving HTC or OCC dust. The text then presents the first part of an example of this pattern, describing an ablation rate of 28% for iron in AST dust. The information that iron from HTC dust had an ablation rate of 90% is therefore the most effective way to complete this example—the comparison of a relatively low ablation rate for iron in slower-moving AST dust with a relatively high ablation rate for iron in faster-moving HTC dust illustrates the tendency of ablation rates for a given element to be lower in slower-moving dust than in faster-moving dust."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates that SPC dust, like AST dust, moves relatively slowly; a comparison of the ablation rates of iron from two slower- moving dust sources could not be an example of the difference between ablation rates in slower-moving dust and faster-moving dust, which is the pattern that the example is supposed to illustrate. Choice B is incorrect because the example in the text is supposed to illustrate the difference in the ablation rates of the same element from slower-moving dust and faster-moving dust, and the first part of the example provides data about the ablation rate of iron, which means the second part of the example must also be about the ablation rate of iron, not the ablation rate of sodium. Choice D is incorrect because the example in the text is supposed to illustrate the difference in the ablation rates of the same element from slower- moving dust and faster-moving dust, and the first part of the example provides data about the ablation rate of iron, which means the second part of the example must also be about the ablation rate of iron, not the ablation rate of sodium. Additionally, any ablation rate from AST dust would be ineffective in this example since AST dust is referenced in the first part of the example and thus additional data focused on AST dust would not illustrate a variation across dust types."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from the interviews best illustrates the journalist’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the quotation that best illustrates the journalist’s claim. By indicating that a collective didn’t continue because it was hard to share credit and responsibilities within the group even though the company was enjoyable, the quotation shows that working collaboratively can be difficult for artists who are used to having complete control over their work."}, {"type": "paragraph", "text": "Choice B is incorrect because the quotation indicates that members of a collective are able to collaborate together and have agreed on a fair way to manage their responsibilities; this doesn’t demonstrate the challenge of sharing control among members of a collective. Choice C is incorrect because the quotation highlights the support and encouragement of individual expression an artist experiences due to working in a collective; these positive aspects don’t demonstrate the challenge of sharing control among members of a collective."}, {"type": "paragraph", "text": "Choice D is incorrect because the quotation doesn’t address any challenges of sharing control among members of a collective; it simply indicates that artists sometimes choose to work with collectives without having to be a member. Therefore, the quotation doesn’t illustrate the journalist’s claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most effectively uses data from the table to complete the statement. The text explains that mycorrhizal hosts are plants that benefit from the presence of mycorrhizal fungi in the soil and that some such plants produce more mass when grown in the presence of these fungi, while for nonmycorrhizal species the fungi either have no effect or may be harmful. The experiment included two mycorrhizal hosts (corn and marigold) and one nonmycorrhizal species (broccoli). Given the claim in the text that nonmycorrhizal species will see either no difference or a decrease in mass when exposed to mycorrhizal fungi, the student would likely have been surprised by the higher average mass for broccoli grown in the presence of the fungi than the broccoli grown in the soil treated to kill fungi."}, {"type": "paragraph", "text": "Choice B is incorrect. Although this choice accurately describes the corn data from the table, the fact that the mycorrhizal host corn is more massive in the presence of the fungi likely fits with what the student expected and would therefore not be surprising. Choice C is incorrect. Although this choice accurately describes the marigold data from the table, the fact that the mycorrhizal host marigold is more massive in the presence of the fungi is likely what the student expected and thus would not be surprising. Choice D is incorrect because it does not accurately represent the data in the table—when grown in soil treated to kill fungi, corn had an average mass of 3.8 g while broccoli had an average mass of 7g—and because making comparisons among the plants in the no-fungi condition, by itself, does not provide a basis to compare the average mass of mycorrhizal hosts and nonmycorrhizal species grown in the presence of the fungi with those grown in the soil treated to kill fungi."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the conclusion that most logically completes the text’s discussion about the significance of the cupid found at Pompeii. The text indicates that the cupid is near a statue of a female figure who is fishing, and it goes on to indicate that because Venus is associated with cupids, some scholars believe the female figure to be the goddess Venus. But the text then says that, according to archaeologist Carla Brain, cupids may have also been associated with the activity of fishing, which, if true, would suggest that the mere appearance of a cupid near a female figure engaged in fishing does not indicate with certainty that the figure is Venus (that is, the cupid might be associated with fishing, and the figure might be anyone at all)."}, {"type": "paragraph", "text": "Choice B is incorrect because the text says nothing about how often Venus was depicted fishing in Roman art: it only implies that in certain instances a female figure may or may not be Venus. Choice C is incorrect because Carla Brain’s proposed explanation for the presence of the cupids makes no reference to the female figure, and so the possibility that the figure in the artworks is in fact Venus cannot be definitively eliminated. Choice D is incorrect because there is nothing in the text to suggest that the only reasonable way to interpret the figure is as Venus."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of plural and possessive nouns. The plural possessive noun “people’s” and the plural noun “stories” correctly indicate that there are multiple stories from multiple people."}, {"type": "paragraph", "text": "Choice B is incorrect because the context requires the plural possessive noun “people’s” and the plural noun “stories,” not the plural noun “peoples” and the singular possessive noun “story’s.” Choice C is incorrect because the context requires the plural possessive noun “people’s,” not the plural noun “peoples.”"}, {"type": "paragraph", "text": "Choice D is incorrect because the context requires the plural noun “stories,” not the singular possessive noun “story’s.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb “survives” correctly indicates that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose."}, {"type": "paragraph", "text": "Choice A is incorrect because the past perfect verb “had survived” doesn’t indicate that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. Choice B is incorrect because the past tense verb “survived” doesn’t indicate that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose. Choice C is incorrect because the conditional verb “would survive” doesn’t indicate that the wood frog regularly survives subfreezing temperatures by producing large amounts of glucose."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (“Defying…fast”) and another sentence that begins with a supplementary phrase (“During…Olympics”)."}, {"type": "paragraph", "text": "Choice A is incorrect. When a dash is present in a sentence (“ran—fast”), it’s not conventional to use another dash (“fast—during”) to mark the boundary between sentences because it creates a potentially confusing sentence. In this context, a period, semicolon, or colon would be clear and more conventional. Choice B is incorrect because it results in a run-on sentence. The sentences (“Defying…fast”) and (“during…Olympics”) are fused without punctuation and/or a conjunction."}, {"type": "paragraph", "text": "Choice C is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between sentences."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb “is” agrees in number with the singular subject “the triangle.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “are” doesn’t agree in number with the singular subject “the triangle.” Choice B is incorrect because the plural verb “have been” doesn’t agree in number with the singular subject “the triangle.”"}, {"type": "paragraph", "text": "Choice C is incorrect because the plural verb “were” doesn’t agree in number with the singular subject “the triangle.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (“In 2004…sampler”) and the second main clause (“in 2014…pillars”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. The word “later” is an adverb and cannot be used to join two main clauses unless it is preceded by a conjunction. Choice C is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. The word “later” is an adverb and cannot be used to join two main clauses unless it is preceded by a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase “Julian’s 1935 synthesis” the subject of the sentence and places it immediately after the modifying phrase “named…years.” In doing so, this choice clearly establishes that Julian’s 1935 synthesis of the alkaloid physostigmine—and not another noun in the sentence— was named in 1999 as one of the greatest achievements by a US chemist in the past hundred years."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a dangling modifier. The placement of the noun “Julian” immediately after the modifying phrase illogically suggests that Julian himself was named as one of the greatest achievements by a US chemist in the past hundred years. Choice B is incorrect because it results in a dangling modifier. The placement of the prepositional phrase “in 1935” immediately after the modifying phrase illogically and confusingly suggests that “in 1935” was named as one of the greatest achievements by a US chemist in the past hundred years. Choice D is incorrect because it results in a dangling modifier. The placement of the noun phrase “the alkaloid physostigmine” immediately after the modifying phrase illogically and confusingly suggests that the alkaloid physostigmine itself (not the synthesis of it) was named as one of the greatest achievements by a US chemist in the past hundred years."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the punctuation of items in a complex series (a series including internal punctuation). The semicolon after “nonnative” is correctly used to separate the first item (“growing diverse plant species, both native and nonnative”) and the second item (“fostering scientific research”) in the series of things that botanical gardens are dedicated to. Further, the comma after “species” is correctly used to separate the noun phrase “diverse plant species” and the supplementary phrase “both native and nonnative” that modifies it."}, {"type": "paragraph", "text": "Choice A is incorrect because a comma (specifically, the comma after “nonnative”) can’t be used in this way to separate items in a complex series."}, {"type": "paragraph", "text": "Choice C is incorrect because a semicolon can’t be used in this way to separate the noun phrase “diverse plant species” and the supplementary phrase “both native and nonnative” that modifies it. Further, a comma can’t be used in this way to separate items in a complex series. Choice D is incorrect because it fails to use appropriate punctuation to separate the noun phrase “diverse plant species” and the supplementary phrase “both native and nonnative” that modifies it. Further, a comma can’t be used in this way to separate items in a complex series."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the punctuation of a supplementary word or phrase between two main clauses. This choice correctly uses a comma to separate the supplementary adverb “however” from the preceding main clause (“Okinaka doesn’t…single-handedly”) and a semicolon to join the next main clause (“all…culture”) to the rest of the sentence. Further, placing the semicolon after “however” correctly indicates that the information in the preceding main clause (Okinaka doesn’t make such decisions single- handedly) is contrary to what might be assumed from the information in the previous sentence (Okinaka sits on the review board that adds new sites to the Hawaii Register of Historic Places)."}, {"type": "paragraph", "text": "Choice B is incorrect because placing the semicolon after “single-handedly” and the comma after “however” illogically indicates that the information in the next main clause (all historical designations must be approved by a group of experts) is contrary to the information in the previous clause (Okinaka doesn’t make such decisions single-handedly). Choice C is incorrect because it results in a comma splice. Commas can’t be used in this way to punctuate a supplementary word or phrase between two main clauses. Choice D is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “Finally” logically signals that the bill passing— following many attempts between 1968 and 1983—is the final, concluding event in the sequence described in the previous sentences."}, {"type": "paragraph", "text": "Choice A is incorrect because “instead” illogically signals that the bill passing is an alternative to one of the events described in the previous sentences. It is the final event in the sequence. Choice B is incorrect because “likewise” illogically signals that the bill passing is similar to one of the events described in the previous sentences. Instead, it is the final event in the sequence. Choice D is incorrect because “additionally” illogically signals that the bill passing is merely another event described along with the events of the previous sentences. Instead, it is the final, concluding event in the sequence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “However” logically signals that this sentence, which indicates that the Pūhāhonu volcano may be larger than the Mauna Loa volcano, offers a contrast to or refutation of the previous assumption that Mauna Loa is the largest shield volcano."}, {"type": "paragraph", "text": "Choice A is incorrect because “secondly” illogically signals that this sentence merely offers an additional or secondary point concerning the previous assumption that Mauna Loa is the largest shield volcano. Instead, the sentence offers a contrast to or refutation of that assumption. Choice B is incorrect because “consequently” illogically signals that this sentence offers a result or consequence of the previous assumption that Mauna Loa is the largest shield volcano. Instead, the sentence offers a contrast to or refutation of that assumption. Choice C is incorrect because “moreover” illogically signals that this sentence merely adds to the previous assumption that Mauna Loa is the largest shield volcano. Instead, the sentence offers a contrast to or refutation of that assumption."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “In addition” logically signals that the detail in this sentence—that Coleridge-Taylor included traditional African music in his classical compositions—adds to the information in the previous sentence. Specifically, the previous sentence indicates one way in which Coleridge-Taylor emphasized his mixed-race ancestry, and the claim that follows indicates a second, additional way."}, {"type": "paragraph", "text": "Choice B is incorrect because “actually” illogically signals that the detail in this sentence is surprising in light of the information in the previous sentence. Instead, the detail adds to the information, indicating a second, additional way in which Coleridge-Taylor emphasized his mixed-race ancestry. Choice C is incorrect because “however” illogically signals that the detail in this sentence contrasts with the information in the previous sentence. Instead, the detail adds to the information, indicating a second, additional way in which Coleridge-Taylor emphasized his mixed-race ancestry. Choice D is incorrect because “regardless” illogically signals that the detail in this sentence is true despite the information in the previous sentence. Instead, the detail adds to the information, indicating a second, additional way in which Coleridge-Taylor emphasized his mixed-race ancestry."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Therefore” logically signals that the action described in this sentence—the researchers theorizing that the dish was named for its effect on diners—is a result or consequence of the previous observation that the dish had a calming effect."}, {"type": "paragraph", "text": "Choice B is incorrect because “alternately” illogically signals that the action described in this sentence offers an alternative or contrast to the previous observation that the dish had a calming effect. Instead, the action is a result or consequence of that observation. Choice C is incorrect because “nevertheless” illogically signals that the action described in this sentence occurs despite the previous observation that the dish had a calming effect. Instead, the action is a result or consequence of that observation. Choice D is incorrect because “likewise” illogically signals that this sentence merely adds a second, similar detail to the previous observation that the dish had a calming effect. Instead, this sentence describes an action that is a result or consequence of that observation."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence emphasizes a difference between baking soda and baking powder, noting that baking soda needs to be mixed with an acidic ingredient to produce carbon dioxide but baking powder doesn’t."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence focuses on what bakers use to make batters rise; it doesn’t emphasize a difference between baking soda and baking powder."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence provides a general description of baking soda and baking powder; it doesn’t emphasize a difference between them. Choice C is incorrect. The sentence explains what baking soda and honey are; it doesn’t emphasize a difference between baking soda and baking powder."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence effectively describes Unwoven Light to an audience unfamiliar with Park, noting that Soo Sunny Park is a Korean American artist and that the 2013 work consists of colorful prisms formed by light passing through iridescent tiles."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes aspects of Unwoven Light but doesn’t mention who Park is; it thus doesn’t effectively describe the work to an audience unfamiliar with Park. Choice B is incorrect. Although the sentence indicates when the work was created and who Park is, it lacks descriptive details and thus doesn’t effectively describe Unwoven Light. Choice C is incorrect. The sentence mentions Park and describes an aspect of Unwoven Light—the chain- link fence—but doesn’t effectively describe the overall work to an audience unfamiliar with the artist."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence effectively presents Tan’s research to an audience unfamiliar with Angkor Wat, explaining the results of the research and identifying Angkor Wat as a temple in Cambodia."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence presents Tan’s research, it fails to explain what Angkor Wat is for an audience unfamiliar with the temple. Choice B is incorrect. The sentence emphasizes the role that decorrelation stretch analysis played in Tan’s research; it doesn’t present the research, which would require specifying where it was conducted. Choice D is incorrect. While the sentence explains what Angkor Wat is, it fails to present Tan’s research."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the fashion resale market’s continued growth. As used in this context, “predicted” means forecast, or indicated that something would happen in the future. The text indicates that the fashion resale market made a lot of money in 2019 and that some analysts expected the market to continue to grow. This context suggests that the analysts believed that the fashion resale market was going to make more money than it had already made, with the analysts indicating that revenues would more than double by 2028."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make sense in context to say that some analysts “produced,” or manufactured or brought about, the increase in future revenues of the fashion resale market. The analysts themselves couldn’t have brought about the future revenue growth, since, as the text suggests, they were merely in the position of drawing conclusions about future fashion resale market revenue based on 2019 revenue. Choice B is incorrect because the text indicates that some analysts expected the fashion resale market to continue to grow in the future, not that they “denied,” or rejected, this notion. Nothing in the text supports the idea that these analysts thought the revenues wouldn’t grow."}, {"type": "paragraph", "text": "Choice C is incorrect because the text indicates that some analysts expected the fashion resale market to continue to grow in the future, not that they “worried,” or felt concerned, that revenue would significantly increase by 2028. Nothing in the text suggests that the analysts felt concerned about the increase; rather, the text suggests that the increase would represent a favorable outcome, since it would mean that the fashion resale market grew to generate even more revenue."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of delivering biomolecules to plant cells. In this context, “overcome” means to succeed in dealing with an obstacle. The text suggests that although it’s difficult to move biomolecules through plant cell walls, Landry and her colleagues have shown that carbon nanotubes may be useful, since they can cross cell walls. This context conveys that Landry and her colleagues think it’s possible, using carbon nanotubes, to succeed in dealing with the obstacle of transmitting biomolecules to plant cells."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make sense in context to say that Landry and her colleagues have shown that it may be possible to “conceptualize,” or form an idea of, the difficulty of transmitting biomolecules through the walls of plant cells. The text presents this difficulty as a known problem that Landry and her colleagues think they may have solved, not as a mysterious occurrence that they have yet to form ideas about. Choice B is incorrect because the text suggests that Landry and her colleagues think it may be possible to successfully deal with the problem of transmitting biomolecules through the walls of plant cells, not that Landry and her colleagues think it may be possible to “neglect,” or simply to disregard and ignore the problem. Choice C is incorrect because it wouldn’t make sense in context to say that Landry and her colleagues have shown that it may be possible to “illustrate,” or demonstrate, the difficulty of transmitting biomolecules through the walls of plant cells by using carbon nanotubes. According to the text, carbon nanotubes allow molecules to be transmitted to plant cells—something that is otherwise difficult to do. The text therefore presents carbon nanotubes as a way of possibly solving a problem, not as a means of demonstrating the problem."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of the work of particle physicists. In this context, “inspecting” means viewing closely in order to examine. The text indicates that as particle physicists, Arce and El-Khadra’s work involves using advanced technology to “closely examine” subatomic particles. In other words, they use technology to inspect small parts of matter that can’t be seen by the naked eye."}, {"type": "paragraph", "text": "Choice A is incorrect because nothing in the text suggests that Arce and El-Khadra spend time “selecting,” or choosing, subatomic particles for some purpose; the text simply states that the particle physicists use advanced technology to see and study the behavior of those tiny parts of matter. Choice C is incorrect because nothing in the text suggests that Arce and El-Khadra spend time “creating” subatomic particles, or bringing them into existence; the text simply states that the particle physicists use advanced technology to see and study the behavior of those tiny parts of matter."}, {"type": "paragraph", "text": "Choice D is incorrect. In this context, “deciding” would mean making a final choice or judgment about something. It wouldn’t make sense to say that particle physicists get to choose what is and isn’t visible to the naked eye, especially when the text presents it as fact that subatomic particles are “the smallest detectable parts of matter” and would therefore be invisible. The text focuses on Arce and El-Khadra’s close observation of those particles, not on any decisions they might make."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of the fossilized bones of the hominin known as Little Foot. As used in this context, “comparable to” would mean similar to. The text indicates that the relationship between the fossilized clavicle and shoulder bones of Little Foot and the clavicle and shoulder bones of “frequent climbers,” such as chimpanzees and gorillas, suggests that Little Foot had adapted to moving around in trees. This context suggests that the relationship between the fossilized bones of Little Foot and the bones of chimpanzees and gorillas is one of similarity—the Little Foot fossils are likely comparable to the modern ape bones."}, {"type": "paragraph", "text": "Choice A is incorrect because if the fossilized bones of Little Foot were “surpassed by,” or exceeded by or made inferior to, the bones of modern apes that are frequent climbers, it wouldn’t suggest, as the text says, that Little Foot was adapted to moving around in trees. If anything, learning that Little Foot’s clavicle and shoulder bones were surpassed by those of chimpanzees and gorillas would suggest that Little Foot was poorly adapted to climbing. Choice C is incorrect because if Little Foot’s fossilized clavicle and shoulder bones were “independent of,” or not influenced by or affiliated with, the bones of modern apes that climb often, it wouldn’t suggest, as the text says, that Little Foot was adapted to moving around in trees. Choice D is incorrect because the text indicates that Little Foot’s fossilized bones date to 3.6 million years ago, so they couldn’t have been “obtained from,” or acquired from, the bones of modern apes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Samuel R. Delany’s character Rydra Wong. As used in this context, “atypical” would mean unrepresentative or not common. The text indicates that Wong is one of “nearly a dozen” characters in Delany’s novels who are poets or writers. This context conveys that being a poet isn’t an atypical occupation for a character in one of Delany’s works."}, {"type": "paragraph", "text": "Choice A is incorrect because “infallible” means to be accurate or without fault, which wouldn’t make sense in context. The text focuses on the fact that Delany has written many characters who are poets and writers. This context suggests that the occupation isn’t atypical for Delany, not that the occupation isn’t infallible, or problematic. Choice C is incorrect because “lucrative” means to be profitable, which wouldn’t make sense in context. If writing poet characters weren’t profitable, it wouldn’t be logical to explain this by citing that Delany gave many of his characters the same occupation. Choice D is incorrect because “tedious” means to be boring, which wouldn’t make sense in context. The text focuses on the fact that Delany has written many characters who are poets and writers. This context suggests that the occupation isn’t atypical for Delany, not that the occupation isn’t tedious."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically and precisely completes the text’s discussion of Jeyifous’s series of images for the 2020 exhibition. In this context, “created” means produced. The text explains that Jeyifous, a photographer and neurobiologist, photographed adults who had appeared as children in posters from the 1970s, then combined those photographs with magnified images of the adults’ cells—a process that resulted in what he called “micro and macro portraiture.” This context suggests that Jeyifous drew on his dual interests in photography and neurobiology to produce the images for display in the exhibition."}, {"type": "paragraph", "text": "Choice A is incorrect because there’s nothing in the text to suggest that Jeyifous “validated,” or corroborated, the series of images. The text describes Jeyifous’s process for composing the images but doesn’t describe Jeyifous making an effort to evaluate the images for their artistic or scientific legitimacy. Choice C is incorrect because there’s nothing in the text to suggest that Jeyifous “challenged,” or disputed, an aspect of the images; rather, the focus of the text is on the inspiration behind the images and the method Jeyifous used to achieve them."}, {"type": "paragraph", "text": "Choice D is incorrect because the text indicates that Jeyifous made the images himself using a combination of photography and magnified pictures of cells, not that he “restored,” or reconditioned, the images from a deteriorated state."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of Francis Cecil Sumner. As used in this context, “proponent of” means supporter of. The text says that Sumner helped to found the psychology department at historically Black Howard University in 1930. This is evidence that Sumner supported increasing the opportunity for Black students to study psychology."}, {"type": "paragraph", "text": "Choice B is incorrect because the phrase “supplement to,” or addition to, wouldn’t make sense in context. The text discusses Sumner’s efforts to increase the number of Black psychology students, but it doesn’t make sense to describe him as an addition to his efforts. Choice C is incorrect because Sumner was already an accomplished psychologist himself when he helped to found the Howard University psychology department. While Black students were the beneficiaries of his efforts—that is, they received help because of his efforts—it wouldn’t make sense in this context to describe Sumner as a “beneficiary of” opportunities, because he was the one doing the helping. Choice D is incorrect because founding a psychology department at Howard University wouldn’t be a “distraction for” Sumner’s aim to increase the opportunity for Black students to study psychology—that is, it wouldn’t be something that draws Sumner’s attention away from that goal, but rather the opposite."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of the legitimacy of the reigns of French monarchs such as Hugh Capet and Henry I. As used in this context, “buttress” means to strengthen or defend. The text indicates that regardless of whether a French monarch’s reign was significant or uneventful, each monarch faced questions about his right to the throne. The text goes on to say that in order to understand the path of a French monarch’s reign, it’s important to understand what contributed to the monarch’s ability to “hold the throne.” This context suggests that French monarchs such as Hugh Capet and Henry I had to buttress, or defend, their right to be monarch."}, {"type": "paragraph", "text": "Choice A is incorrect. Saying that a monarch who is faced with questions about the legitimacy of his reign was able to “reciprocate” his right to the French throne would mean that he either returned his right to the throne or that he responded in kind to the challenge. Neither of these meanings would make sense in context because the text focuses on people who did reign as French monarchs and defended their right to do so. Choice B is incorrect because it wouldn’t make sense in context to discuss factors that enabled a monarch to “annotate,” or add notes to or explain, his right to the French throne. Nothing in the text suggests that the monarchs were writing notes about their right to the throne; instead, faced with questions about the legitimacy of their reign, the monarchs defended their right. Choice D is incorrect because it wouldn’t make sense in context to discuss factors that enabled a monarch to “disengage,” or withdraw his right to the French throne. The text focuses on an examination of people who reigned as French monarchs, not on people who didn’t choose to rule."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it best describes how the underlined sentence functions in the text as a whole. The first two sentences establish that birds of some species don’t raise their own young; instead, they lay their eggs in the nests of birds of other species. The underlined sentence then states that female cuckoo birds engage in this behavior, having been observed specifically laying their eggs in other nests while the other birds are out finding food. According to the text, the cuckoo chicks are then raised by the other birds. Thus, the underlined sentence provides a particular detail about how female cuckoos carry out the behavior of laying eggs for other birds to raise."}, {"type": "paragraph", "text": "Choice A is incorrect. Rather than mentioning a physical feature of female cuckoos, the underlined sentence introduces a specific behavior of female cuckoos: laying eggs in the nests of birds of other species when the other birds are away. The only reference to physical features is the last sentence’s general mention of cuckoo chicks looking different from chicks of other species. Choice B is incorrect because the underlined sentence refers to the nests of birds other than cuckoos and doesn’t describe how any nests look, cuckoo or otherwise. Instead, the sentence addresses how female cuckoos use other birds’ nests. Choice D is incorrect because the underlined sentence describes only female cuckoo behavior (laying eggs in the nests of birds of other species when the other birds are away); it’s the last sentence of the text that addresses the other birds’ reaction, indicating that those birds usually raise the cuckoo chicks once they’ve hatched."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, how did the researchers determine the level of surprise displayed by the cats in the study?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it explains how the researchers determined the level of surprise displayed by the cats in the study. The text states that Saho Takagi and colleagues played recordings of the voice of each cat’s owner and measured how surprised the cat was by the recording based on how it moved its ears and head."}, {"type": "paragraph", "text": "Choice B is incorrect because, as the text explains, the recordings played for each cat in the study were of the voice of the cat’s owner, not a stranger’s voice."}, {"type": "paragraph", "text": "Choice C is incorrect because the text explains that during the study, the cats didn’t interact directly with their owners; instead, the cats listened to recordings of their owners’ voices. Choice D is incorrect because the text doesn’t indicate that the researchers monitored the cats’ movement around the room in which the study was conducted."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly weaken the student’s hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it describes an experimental outcome that would most directly weaken the student’s hypothesis. According to the text, the student hypothesizes that Brassica rapa parachinensis (choy sum) will benefit more from acidic soil than it will from neutral soil. The text then explains that the student planted 16 choy sum seeds in potting soil with coffee grounds added to increase acidity and another 16 seeds in soil without coffee grounds as a control (a group identical to the experimental group except for the experimental modification being tested). If the hypothesis were correct, the plants in the more acidic soil-and-coffee-grounds mixture would grow faster than those in the control group. However, choice A proposes a scenario in which the plants in soil without coffee grounds were “significantly taller” than those in the more acidic mixture—an outcome that weakens the hypothesis that higher acidity is beneficial to the plants’ growth."}, {"type": "paragraph", "text": "Choice B is incorrect. If the choy sum planted in the neutral soil produced less plant matter and therefore weighed less than the choy sum planted in the acidic soil-and-coffee-grounds mixture, this finding would strengthen the student’s hypothesis, not weaken it. Choice C is incorrect. If seeds planted in neutral soil (without coffee grounds) sprouted significantly later than seeds planted in the acidic soil-and-coffee -grounds mixture, this finding would strengthen, not weaken, the student’s hypothesis that acidic soil benefits choy sum. Choice D is incorrect. If seeds planted in the neutral soil (without coffee grounds) sprouted significantly fewer plants than seeds planted in the acidic soil-and-coffee- grounds mixture did, this finding would strengthen, not weaken, the student’s hypothesis that choy sum benefits from acidic soil."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from “The Young Girl” most effectively illustrates the claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most effectively illustrates the claim in the text that in describing the teenaged girl, Mansfield contrasts the character’s pleasant appearance with her unpleasant attitude. In the quotation, Mansfield describes the teenager as having a “lovely nose” (a compliment about her appearance) but also as treating her makeup puff “as though she loathed it” (a judgment suggesting her unpleasant attitude)."}, {"type": "paragraph", "text": "Choice A is incorrect because the teenager′s reaction to the flowers doesn’t make it clear that she has an unpleasant attitude, and nothing in the quotation indicates that any part of her appearance is pleasant. Choice C is incorrect because the quotation suggests that the teenager has an unpleasant attitude (being upset with the location and leaving the table before the narrator has paid for the meal) but doesn’t give any indication that she has a pleasant appearance. Choice D is incorrect because the quotation suggests that the teenager may have an unpleasant attitude (lowering her eyes, wincing, and sitting in silence) but doesn’t give any indication that any part of her appearance is pleasant."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to illustrate the claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it uses data from the graph to effectively illustrate the text’s claim about general economic policy uncertainty in the United Kingdom. The graph presents values for economic policy uncertainty in tax and public spending policy, trade policy, and general economic policy in the UK from 2005 to 2010. The graph shows that in 2005, the value for general economic policy uncertainty (approximately 90) was substantially lower than the value for uncertainty about trade policy specifically (approximately 160). It also shows that in 2010, the value for general economic policy uncertainty (approximately 120) was substantially higher than the value for uncertainty about trade policy (approximately 70). The substantial differences between these values in 2005 and 2010 support the claim that a general measure may not fully reflect uncertainty about specific areas of policy."}, {"type": "paragraph", "text": "Choice A is incorrect because the graph shows that the level of general economic policy uncertainty was similar to the level of uncertainty about tax and public spending policy in both 2005 (with values of approximately 90 and 100, respectively) and 2009 (with values of approximately 80 and 75, respectively)."}, {"type": "paragraph", "text": "Choice B is incorrect because the graph shows that general economic policy uncertainty was higher than uncertainty about tax and public spending policy in 2006, 2007, and 2009, not that it was lower each year from 2005 to 2010."}, {"type": "paragraph", "text": "Choice C is incorrect because the graph shows that general economic policy uncertainty reached its highest level in 2010, which was when uncertainty about tax and public spending policy also reached its highest level, not its lowest level."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding from the students’ study, if true, would most strongly support Tannen’s hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents the finding that, if true, would most strongly support Tannen’s hypothesis. According to the text, Tannen’s hypothesis is that multiple perspectives presented in a noncompetitive format is more informative than a debate between opposing viewpoints is. If participants who saw a panel of three commentators with various views about an issue answered more questions about the issue correctly than did participants who saw a debate, that would support Tannen’s hypothesis since it would show that participants who heard multiple varied perspectives were better informed than were participants who heard a debate between opposing viewpoints."}, {"type": "paragraph", "text": "Choice A is incorrect because finding that participants perceived commentators in the debate as more knowledgeable than commentators in the panel is irrelevant to Tannen’s hypothesis, which is that presenting multiple perspectives on an issue is more informative to the audience than presenting opposing views of the issue is. Participants’ perception of how knowledgeable panelists are has no bearing on how much participants learn from the panelists. Choice B is incorrect because finding that participants perceived commentators in the panel as more knowledgeable than a single commentator is irrelevant to Tannen’s hypothesis, which is that presenting multiple perspectives on an issue is more informative to the audience than presenting opposing views of the issue is. Participants’ perception of how knowledgeable panelists are has no bearing on how much participants learn from the panelists, and Tannen’s hypothesis says nothing about how informative single commentators are. Choice D is incorrect because finding that participants who watched a single commentator answered more questions correctly than participants who watched the debate did wouldn’t be relevant to Tannen’s hypothesis, which is that hearing multiple varying perspectives is more informative than hearing a debate. Tannen’s hypothesis says nothing about how informative single commentators are."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses a quotation from King Lear to illustrate the claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most effectively uses a quotation from King Lear to illustrate the claim that King Lear expresses regret for his actions. In the quotation, Lear describes striking himself on the head—the same act he’s engaged in as he speaks, and one that suggests he’s deeply upset with himself. Referring to himself in the second person (with “thy”), the character exclaims “Beat at this gate that let thy folly in / And thy dear judgement out!” Lear refers metaphorically to his own mind as a gate that has allowed folly, or poor judgement, to enter and good judgement to escape. This suggests that Lear regrets his attempts to test his three daughters’ devotion to him, regarding those attempts as examples of the folly that has entered the gate of his mind."}, {"type": "paragraph", "text": "Choice A is incorrect because this quotation doesn’t express King Lear’s sense of regret over his own actions; instead, it expresses his belief that the harm that others have done to him (or the extent to which they have “sinned against” him) outweighs whatever harm he himself has caused by “sinning.” Choice B is incorrect because this quotation doesn’t express King Lear’s sense of regret over his own actions; instead, it expresses his thoughts about an approaching storm (“this tempest”), which he believes “will not give [him] leave to ponder,” or time to consider, the harm that he will continue to experience (“things” that “would hurt [him] more”). Choice D is incorrect because this quotation expresses King Lear’s vow to commit terrible actions (or “things” that “shall be / The terrors of the earth”) in the future, not his regret over actions that he’s already taken."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the relative appeal of different kinds of plays by Shakespeare to today’s audiences. According to the text, Shakespeare’s tragedies address broad themes that continue to appeal to today’s audiences. Indeed, the text suggests that these themes are timeless, as illustrated by the example of Romeo and Juliet, which the text states is still read and widely performed despite being set in the Italy of Shakespeare’s time. In contrast, the text indicates that audiences and readers may need to be familiar with several centuries of English history in order to understand Shakespeare’s history plays. Because many theatergoers and readers are unlikely to possess such extensive historical knowledge, it follows that they are likely to find Shakespeare’s history plays less engaging than his more accessible tragedies."}, {"type": "paragraph", "text": "Choice B is incorrect because the text never introduces a comparison between Shakespeare’s tragedies and twentieth-century plays, only between Shakespeare’s tragedies and his history plays. Since twentieth-century plays aren’t mentioned, there’s no basis in the text for the idea that some of Shakespeare’s tragedies are more relevant than twentieth-century plays to today’s audiences. Choice C is incorrect. Although the text indicates that Romeo and Juliet is thematically accessible to today’s audiences, it doesn’t suggest that Romeo and Juliet is more accessible than Shakespeare’s other tragedies. Rather, the text presents Romeo and Juliet as an example to support the idea that Shakespeare’s tragedies hold continued appeal for today’s readers and theatergoers. Choice D is incorrect. Although experts in English history would likely possess the knowledge needed to understand Shakespeare’s history plays, the text never mentions such experts or suggests that they would enjoy the history plays more than Shakespeare’s other works."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents the conclusion that most logically follows from the text’s discussion of Ancestral Puebloans’ migration to the Rio Grande Valley. The text states that in the late 1200s C.E., the Ancestral Puebloan civilization abandoned villages in its original homeland, which included the Mesa Verde site. The text goes on to say that recent genetic analysis has demonstrated that the modern turkey population in the Rio Grande Valley descends partly from the ancient turkeys raised at Mesa Verde, and that the genetic markers shared by the two turkey populations first appeared at Mesa Verde only after 1280 C.E. Therefore, it can reasonably be concluded that some Ancestral Puebloans migrated to the Rio Grande Valley in the late 1200s and carried their agricultural practices—including the farming of turkeys— to their new home."}, {"type": "paragraph", "text": "Choice A is incorrect because the text never compares the condition of the Rio Grande Valley’s terrain to that of Mesa Verde’s terrain, either in the present or in the past. Choice C is incorrect. Although genetic analysis has demonstrated that the modern turkey population in the Rio Grande valley descended in part from the turkey population raised by the Ancestral Puebloans of Mesa Verde before their migration to the valley in 1280, this finding doesn’t eliminate the possibility that Indigenous peoples living in the valley before 1280 might also have farmed turkeys. Choice D is incorrect. The text doesn’t consider the possibility that before their migration to the Rio Grande Valley after 1280, the Ancestral Puebloans of Mesa Verde might have adopted turkey farming from an outside Indigenous civilization in another region; instead, the text provides evidence suggesting that the Ancestral Puebloans brought turkey farming to another region— the Rio Grande Valley—after 1280."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents the conclusion that most logically follows from the text’s discussion of the challenge researchers face when studying the effects of holding elected office on a person’s behavior. The text explains that it’s hard for researchers to test for the effects that elected office has on people because finding people to serve as a control group is difficult. The text indicates that a control group needs to be made up of people who share characteristics of the group being tested but don’t have the variable being tested (in this case, holding elected office). Because researchers aren’t able to influence who wins elections, they’re also unable to determine who would serve as an appropriately similar member of a control group. Thus, it logically follows that researchers will find it difficult to identify a group of people who can function as an appropriate control group for their studies."}, {"type": "paragraph", "text": "Choice A is incorrect because the text focuses on the struggle to put together a control group for experiments; it doesn’t suggest that finding information about politicians’ behavior is difficult. Choice B is incorrect because the experiments mentioned in the text are testing the effects of holding elected office on a person’s behavior. Studying people who have already held elected office wouldn’t provide an opportunity to note any behavioral changes that the position might cause."}, {"type": "paragraph", "text": "Choice C is incorrect because the text defines people in a control group as those “who are otherwise similar to the office-holders”; selecting people who differ from the office-holders wouldn’t fit the criteria for an appropriate control group."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of plural and possessive nouns. The plural nouns “stories” and “immigrants” correctly indicate that the memoir tells multiple stories of multiple immigrants."}, {"type": "paragraph", "text": "Choice A is incorrect because the context requires the plural noun “stories,” not the singular possessive noun “story’s.” Choice B is incorrect because the context requires the plural nouns “stories” and “immigrants,” not the singular possessive noun “story’s” and the plural possessive noun “immigrants’.” Choice D is incorrect because the context requires the plural nouns “stories” and “immigrants,” not the plural possessive noun “stories’” and the singular possessive noun “immigrant’s.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is punctuation between a preposition and its complement. No punctuation is needed between the preposition “of” and its complement, the noun phrase “healing, self-discovery, and memory.”"}, {"type": "paragraph", "text": "Choice B is incorrect because no punctuation is needed between a preposition and its complement. Choice C is incorrect because no punctuation is needed between a preposition and its complement. Choice D is incorrect because no punctuation is needed between a preposition and its complement."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use and punctuation of an integrated relative clause. This choice correctly uses the relative pronoun “that” and no punctuation to create an integrated relative clause that provides essential information about the noun phrase (“a book packaging company”) that it modifies."}, {"type": "paragraph", "text": "Choice A is incorrect because it doesn’t use a relative pronoun to link the verb phrase beginning with “specializes” to the noun phrase that it modifies (“a book packaging company”). Choice C is incorrect because it doesn’t use a relative pronoun to link the verb phrase beginning with “specializes” to the noun phrase that it modifies (“a book packaging company”). Choice D is incorrect because no punctuation is needed between the integrated relative clause beginning with “that specializes” and the noun phrase that it modifies (“a book packaging company”)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after “(13C)” pairs with the comma after “isotope” to separate the supplementary element “carbon-13 (13C)” from the rest of the sentence. This supplementary element defines the “rare carbon isotope,” and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element “carbon-13 (13C)” from the rest of the sentence."}, {"type": "paragraph", "text": "Choice B is incorrect because it fails to use appropriate punctuation to separate the supplementary element “carbon-13 (13C)” from the rest of the sentence."}, {"type": "paragraph", "text": "Choice C is incorrect because it fails to use appropriate punctuation to separate the supplementary element “carbon-13 (13C)” from the rest of the sentence. The comma after “carbon-13” isn’t necessary because the parentheses around “13C” already separate this element from the rest of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after “walls” is used correctly to mark the boundary between the first sentence (“In...walls”) and the second sentence (“With…techniques”), which starts with a supplementary phrase."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between sentences. Choice B is incorrect because it results in a run-on sentence. The sentences (“In...walls” and “with... paintings”) are fused without punctuation and/or a conjunction. Choice C is incorrect. Without a comma preceding it, the conjunction “so” can’t be used in this way to join sentences."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. The nonfinite to-infinitive “to forge” is correctly used to form a nonfinite (infinitive) clause that explains why the chemists re-created and reprogrammed the DNA-cleaving bacteria."}, {"type": "paragraph", "text": "Choice B is incorrect. Without a comma separating the main clause (“chemists... bacteria”) from the participle “forging,” this choice illogically suggests that the bacteria are forging a tool, which doesn’t make sense. Choice C is incorrect. Without a coordinating conjunction such as “and” placed before it, the finite past tense verb “forged” can’t be used in this way to describe the chemists’ actions. Choice D is incorrect. If read as a finite verb, the present progressive verb “forging” isn’t consistent with the past tense verbs used in this sentence to describe the actions of the chemists. If read as a nonfinite verb, the participle “forging” can’t be used in this way because there is no following main clause for it to modify."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase “the bioswales” the subject of the sentence and places it immediately after the modifying phrase “By reducing… sewers.” In doing so, this choice clearly establishes that the bioswales—and not another noun in the sentence—are reducing runoff flowing into city sewers."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a dangling modifier. The placement of the noun phrase “the mitigation…waterways” immediately after the modifying phrase results in unclear modification. The resulting sentence makes it hard to determine what is responsible for “reducing the runoff”: the bioswales or some other noun in the sentence. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase “the bioswales’ mitigation…waterways” immediately after the modifying phrase results in unclear modification. The resulting sentence makes it hard to determine what is responsible for “reducing the runoff”: the bioswales or some other noun in the sentence. Choice D is incorrect because it results in a dangling modifier. The placement of the noun phrase “street flooding and the resulting pollution” immediately after the modifying phrase illogically suggests that the “flooding and pollution” are reducing runoff flowing into city sewers."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is punctuation use between a main clause and a supplementary phrase. In this choice, a colon is correctly used to mark the boundary between the main clause (“A study… continents”) and the supplementary phrase (“geological…above”) and to introduce the following explanation of the origin of Earth’s continents."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to mark the boundary between the main clause (“A study…continents”) and the supplementary phrase (“geological… above”) with appropriate punctuation. Choice C is incorrect because a semicolon can’t be used in this way to join the main clause (“A study…continents”) and the supplementary phrase (“geological…above”). A semicolon is conventionally used to join two main clauses, whereas a colon is conventionally used to introduce an element that explains or amplifies the information in the preceding clause, making it the better choice in this context. Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with “geological.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Afterward” logically signals that the events described in this sentence—the CEO’s public acknowledgment and apology— occurred after the rocket booster’s failure and are part of a chronological sequence of events."}, {"type": "paragraph", "text": "Choice B is incorrect because “additionally” illogically signals that the events described in this sentence merely occurred in addition to the rocket booster’s failure. Instead, they occurred after the rocket booster’s failure and are part of a chronological sequence of events. Choice C is incorrect because “indeed” illogically signals that the events described in this sentence emphasize or strengthen a statement made in the previous sentence. Instead, they occurred after the rocket booster’s failure and are part of a chronological sequence of events. Choice D is incorrect because “similarly” illogically signals that the events described in this sentence are similar to the rocket booster’s failure. Instead, they occurred after the rocket booster’s failure and are part of a chronological sequence of events."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Alternatively” logically signals that the soil decontamination method described in this sentence—removing toxic metals from the soil via phytoremediation—offers an alternative to the previously described method (removing the contaminated soil from the ground)."}, {"type": "paragraph", "text": "Choice B is incorrect because “specifically” illogically signals that the soil decontamination method described in this sentence specifies or elaborates on an aspect of the previously described method (removing the contaminated soil from the ground). Instead, phytoremediation is an alternative to that method. Choice C is incorrect because “for example” illogically signals that the soil decontamination method described in this sentence is an example of the previously described method (removing the contaminated soil from the ground). Instead, phytoremediation is an alternative to that method. Choice D is incorrect because “as a result” illogically signals that the soil decontamination method described in this sentence is a result or consequence of the previously described method (removing the contaminated soil from the ground). Instead, phytoremediation is an alternative to that method."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence explains an advantage of the Hanke- Henry calendar, noting that it supports more predictable scheduling than does the Gregorian calendar and describing how it does so (by having calendar dates occur on the same day each year)."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence compares the number of days in the Gregorian and Hanke-Henry calendars; it doesn’t explain an advantage of the Hanke-Henry calendar. Choice B is incorrect. While the sentence refers to a possible reason to adopt the Hanke-Henry calendar—that doing so would help solve a problem with the Gregorian calendar—it doesn’t identify the problem or the solution and thus doesn’t explain the advantage of the Hanke-Henry calendar."}, {"type": "paragraph", "text": "Choice D is incorrect. The sentence describes the origins of the Hanke-Henry calendar; it doesn’t explain an advantage of it."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence effectively presents the influence theory to an audience unfamiliar with the Haudenosaunee Confederacy, explaining the theory’s position that the Great Law of Peace influenced the US Constitution while avoiding mention of the Haudenosaunee Confederacy itself."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence broadly emphasizes Johansen’s ideas about the Great Law of Peace; it doesn’t identify the influence theory or effectively present it. Choice B is incorrect. The sentence emphasizes one fact that supports the influence theory; it doesn’t effectively present the theory to an audience unfamiliar with the Haudenosaunee Confederacy. Choice D is incorrect. The sentence makes a broad generalization about Native people’s influence on the founding of the US; it doesn’t effectively present the influence theory."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. Noting that the Sun (9,800°F) is hotter than most stars within 10 parsecs of it, the sentence emphasizes how hot the Sun is relative to nearby stars."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence explains that astronomer Todd Henry determined the classifications for the Sun and several other stars nearby; it doesn’t emphasize how hot the Sun is relative to nearby stars. Choice C is incorrect. The sentence explains that the majority of stars near the Sun are classified as K or M stars; it doesn’t indicate the Sun’s temperature or emphasize how hot it is relative to nearby stars. Choice D is incorrect. While the sentence indicates that the Sun is classified differently than most nearby stars due to its surface temperature, it doesn’t emphasize how hot the Sun is relative to nearby stars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence effectively introduces Cathryn Halverson’s book to an audience already familiar with the Atlantic Monthly, noting the title of Halverson’s book and describing its content without providing background information about the Atlantic Monthly."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence introduces the Atlantic Monthly and mentions that it’s referred to in Cathryn Halverson’s book title; it doesn’t effectively introduce Halverson’s book. Choice C is incorrect. The sentence assumes that the audience is unfamiliar with the Atlantic Monthly, providing background information about the magazine; it doesn’t effectively introduce Halverson’s book to an audience already familiar with the Atlantic Monthly. Choice D is incorrect. While the sentence assumes that the audience is familiar with the Atlantic Monthly, it doesn’t effectively introduce Cathryn Halverson’s book."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence emphasizes a similarity between the two ways a magnificent frigatebird acquires food, noting that neither way requires the seabird to dive into the water."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes how a magnificent frigatebird captures prey without diving into water; it doesn’t emphasize a similarity between the two ways the seabird acquires food. Choice C is incorrect. The sentence notes the term used to describe one of the two ways that magnificent frigatebirds acquire food; it doesn’t emphasize a similarity between the two ways. Choice D is incorrect. The sentence describes the two ways that a magnificent frigatebird acquires food; it doesn’t emphasize a similarity between the two ways."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 4: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-4-math') then
    raise notice 'skipping sat-practice-test-4-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-4-math', 'SAT Practice Test 4: Math', 'Official SAT Practice Test 4 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 209, '[[200, 200], [200, 200], [200, 200], [200, 200], [200, 200], [200, 200], [200, 200], [200, 220], [200, 230], [220, 250], [250, 280], [280, 310], [290, 320], [300, 330], [310, 340], [320, 350], [330, 360], [330, 360], [340, 370], [350, 380], [360, 390], [370, 400], [370, 400], [380, 410], [390, 420], [400, 430], [420, 450], [430, 460], [440, 470], [460, 490], [470, 500], [480, 510], [500, 530], [510, 540], [520, 550], [530, 560], [550, 580], [560, 590], [570, 600], [580, 610], [590, 620], [600, 630], [620, 650], [630, 660], [650, 680], [670, 700], [690, 720], [710, 740], [730, 760], [740, 770], [750, 780], [760, 790], [770, 800], [780, 800], [790, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m1-q01.png", "alt": "Figure for question 1", "width": 279}, {"type": "paragraph", "text": "A group of students voted on five after-school activities. The bar graph shows the number of students who voted for each of the five activities. How many students chose activity 3?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The bar for activity 3 ends just below the 40 line, at $39$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What percentage of $300$ is $75$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{75}{300} = 0.25$, which is $25\\%$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\frac{x^2}{25} = 36"}, {"type": "paragraph", "text": "What is a solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Multiply both sides by $25$: $x^2 = 900$, so $x = 30$ (or $-30$). Only $30$ is listed."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "$3$ more than $8$ times a number $x$ is equal to $83$. Which equation represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "\"$8$ times a number\" is $8x$, and \"$3$ more than\" that is $8x + 3$. Setting it equal to $83$ gives $8x + 3 = 83$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Hana deposited a fixed amount into her bank account each month. The function $f(t) = 100 + 25t$ gives the amount, in dollars, in Hana''s bank account after $t$ monthly deposits. What is the best interpretation of $25$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$25$ multiplies $t$, the number of deposits, so it is the amount added with each deposit: $\\$25$. The $100$ is the starting amount."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A customer spent $\\$27$ to purchase oranges at $\\$3$ per pound. How many pounds of oranges did the customer purchase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$27 \\div 3 = 9$ pounds."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['9']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Nasir bought $9$ storage bins that were each the same price. He used a coupon for $\\$63$ off the entire purchase. The cost for the entire purchase after using the coupon was $\\$27$. What was the original price, in dollars, for $1$ storage bin?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Before the coupon the bins cost $27 + 63 = 90$ dollars, so one bin cost $90 \\div 9 = 10$ dollars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['10']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m1-q08.png", "alt": "Figure for question 8", "width": 94}, {"type": "paragraph", "text": "For the linear function $f$, the table shows three values of $x$ and their corresponding values of $f(x)$. Which equation defines $f(x)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = 29$ is the $y$-intercept, and $f$ increases by $3$ each time $x$ increases by $1$, so the slope is $3$: $f(x) = 3x + 29$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m1-q09.png", "alt": "Figure for question 9", "width": 297}, {"type": "paragraph", "text": "Right triangles $PQR$ and $STU$ are similar, where $P$ corresponds to $S$. If the measure of angle $Q$ is $18^\\circ$, what is the measure of angle $S$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The right angle is at $R$, so $P = 180^\\circ - 90^\\circ - 18^\\circ = 72^\\circ$. Corresponding angles of similar triangles are equal, so $S = 72^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m1-q10.png", "alt": "Figure for question 10", "width": 264}, {"type": "paragraph", "text": "The scatterplot shows the relationship between two variables, $x$ and $y$."}, {"type": "paragraph", "text": "Which of the following equations is the most appropriate linear model for the data shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The points fall from about $y = 9$ near $x = 0$ to about $y = 1$ near $x = 9$: a negative slope (roughly $-0.9$) and a $y$-intercept near $9.4$. Only $y = 9.4 - 0.9x$ fits."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "2.5b + 5r = 80"}, {"type": "paragraph", "text": "The given equation describes the relationship between the number of birds, $b$, and the number of reptiles, $r$, that can be cared for at a pet care business on a given day. If the business cares for $16$ reptiles on a given day, how many birds can it care for on this day?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute $r = 16$: $2.5b + 80 = 80$, so $2.5b = 0$ and $b = 0$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m1-q12.png", "alt": "Figure for question 12", "width": 262}, {"type": "paragraph", "text": "What is an equation of the graph shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line crosses the $y$-axis at $(0, -8)$ and the $x$-axis at $(-8, 0)$, so its slope is $\\dfrac{0 - (-8)}{-8 - 0} = -1$: $y = -x - 8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $\\dfrac{x}{8} = 5$, what is the value of $\\dfrac{8}{x}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{8}{x}$ is the reciprocal of $\\dfrac{x}{8}$, so it equals $\\dfrac{1}{5}$ (or $0.2$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['1/5', '.2']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 24x + y &= 48 \\\\ 6x + y &= 72 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract the second equation from the first: $18x = -24$, so $x = -\\tfrac{4}{3}$. Then $y = 72 - 6x = 72 + 8 = 80$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 14, 'spr', array['80']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Line $t$ in the $xy$-plane has a slope of $-\\dfrac{1}{3}$ and passes through the point $(9, 10)$. Which equation defines line $t$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Point-slope form: $y - 10 = -\\tfrac{1}{3}(x - 9)$, so $y = -\\tfrac{x}{3} + 3 + 10 = -\\tfrac{x}{3} + 13$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f(x) = 206(1.034)^x$ models the value, in dollars, of a certain bank account by the end of each year from $1957$ through $1972$, where $x$ is the number of years after $1957$. Which of the following is the best interpretation of \"$f(5)$ is approximately equal to $243$\" in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x = 5$ means $5$ years after $1957$, which is $1962$, and $f(5)$ is the account''s value then: about $\\$243$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For a certain rectangular region, the ratio of its length to its width is $35$ to $10$. If the width of the rectangular region increases by $7$ units, how must the length change to maintain this ratio?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The length is $\\tfrac{35}{10} = 3.5$ times the width, so a $7$-unit increase in width needs a $3.5 \\times 7 = 24.5$-unit increase in length."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Square P has a side length of $x$ inches. Square Q has a perimeter that is $176$ inches greater than the perimeter of square P. The function $f$ gives the area of square Q, in square inches. Which of the following defines $f$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Square Q''s perimeter is $4x + 176$, so its side is $\\dfrac{4x + 176}{4} = x + 44$ and its area is $(x + 44)^2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\frac{14x}{7y} = 2\\sqrt{w + 19}"}, {"type": "paragraph", "text": "The given equation relates the distinct positive real numbers $w$, $x$, and $y$. Which equation correctly expresses $w$ in terms of $x$ and $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{14x}{7y} = \\dfrac{2x}{y}$, so dividing by $2$ gives $\\dfrac{x}{y} = \\sqrt{w + 19}$. Square both sides: $w + 19 = \\left(\\dfrac{x}{y}\\right)^2$, so $w = \\left(\\dfrac{x}{y}\\right)^2 - 19$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Point $O$ is the center of a circle. The measure of arc $RS$ on this circle is $100^\\circ$. What is the measure, in degrees, of its associated angle $ROS$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A central angle has the same measure as the arc it intercepts: $100^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 20, 'spr', array['100']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The expression $6\\sqrt[5]{3^5x^{45}} \\cdot \\sqrt[8]{2^8x}$ is equivalent to $ax^b$, where $a$ and $b$ are positive constants and $x > 1$. What is the value of $a + b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sqrt[5]{3^5x^{45}} = 3x^9$ and $\\sqrt[8]{2^8x} = 2x^{1/8}$. The product is $6 \\cdot 3x^9 \\cdot 2x^{1/8} = 36x^{73/8}$, so $a + b = 36 + \\tfrac{73}{8} = \\tfrac{361}{8}$ (about $45.13$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 21, 'spr', array['361/8', '45.12', '45.13']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A right triangle has sides of length $2\\sqrt{2}$, $6\\sqrt{2}$, and $\\sqrt{80}$ units. What is the area of the triangle, in square units?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sqrt{80}$ is the longest side, so it is the hypotenuse (check: $8 + 72 = 80$). The legs are $2\\sqrt{2}$ and $6\\sqrt{2}$, so the area is $\\tfrac{1}{2}(2\\sqrt{2})(6\\sqrt{2}) = \\tfrac{1}{2}(24) = 12$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The expression $4x^2 + bx - 45$, where $b$ is a constant, can be rewritten as $(hx + k)(x + j)$, where $h$, $k$, and $j$ are integer constants. Which of the following must be an integer?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Expanding gives $hx^2 + (hj + k)x + kj$, so $kj = -45$. Then $\\dfrac{45}{k} = -j$, which is an integer. The other quotients need not be integers (for example $h = 4$ does not divide $45$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= 2x^2 - 21x + 64 \\\\ y &= 3x + a \\end{aligned}"}, {"type": "paragraph", "text": "In the given system of equations, $a$ is a constant. The graphs of the equations in the given system intersect at exactly one point, $(x, y)$, in the $xy$-plane. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Setting the equations equal: $2x^2 - 24x + (64 - a) = 0$. One intersection means this quadratic has a single (double) root, at $x = -\\dfrac{-24}{2 \\cdot 2} = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An isosceles right triangle has a hypotenuse of length $58$ inches. What is the perimeter, in inches, of this triangle?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each leg is $\\dfrac{58}{\\sqrt{2}} = 29\\sqrt{2}$, so the perimeter is $29\\sqrt{2} + 29\\sqrt{2} + 58 = 58 + 58\\sqrt{2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In the $xy$-plane, a parabola has vertex $(9, -14)$ and intersects the $x$-axis at two points. If the equation of the parabola is written in the form $y = ax^2 + bx + c$, where $a$, $b$, and $c$ are constants, which of the following could be the value of $a + b + c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The vertex is below the $x$-axis and the parabola crosses it twice, so it opens upward: $y = a(x - 9)^2 - 14$ with $a > 0$. Then $a + b + c$ is the value at $x = 1$: $64a - 14$, which is greater than $-14$. Only $-12$ works."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Function $f$ is defined by $f(x) = -a^x + b$, where $a$ and $b$ are constants. In the $xy$-plane, the graph of $y = f(x) - 15$ has a $y$-intercept at $\\left(0, -\\dfrac{99}{7}\\right)$. The product of $a$ and $b$ is $\\dfrac{65}{7}$. What is the value of $a$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At $x = 0$: $-1 + b - 15 = -\\tfrac{99}{7}$, so $b = 16 - \\tfrac{99}{7} = \\tfrac{13}{7}$. Then $a = \\dfrac{65/7}{13/7} = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m2-q01.png", "alt": "Figure for question 1", "width": 292}, {"type": "paragraph", "text": "The line graph shows the estimated number of chipmunks in a state park on April 1 of each year from $1989$ to $1999$."}, {"type": "paragraph", "text": "Based on the line graph, in which year was the estimated number of chipmunks in the state park the greatest?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The highest point on the graph, about $160$, is at $1994$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A fish swam a distance of $5{,}104$ yards. How far did the fish swim, in **miles**? ($1$ mile $= 1{,}760$ yards)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$5{,}104 \\div 1{,}760 = 2.9$ miles."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $12x^3 - 5x^3$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "These are like terms, so subtract the coefficients and keep the power: $12x^3 - 5x^3 = 7x^3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} x + y &= 18 \\\\ 5y &= x \\end{aligned}"}, {"type": "paragraph", "text": "What is the solution $(x, y)$ to the given system of equations?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute $x = 5y$ into the first equation: $6y = 18$, so $y = 3$ and $x = 15$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The point $(8, 2)$ in the $xy$-plane is a solution to which of the following systems of inequalities?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Both coordinates of $(8, 2)$ are positive, so the point satisfies $x > 0$ and $y > 0$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "|x - 5| = 10"}, {"type": "paragraph", "text": "What is one possible solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Either $x - 5 = 10$, giving $x = 15$, or $x - 5 = -10$, giving $x = -5$. Both are correct."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 6, 'spr', array['15', '-5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 7x + 1"}, {"type": "paragraph", "text": "The function gives the total number of people on a company retreat with $x$ managers. What is the total number of people on a company retreat with $7$ managers?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(7) = 7(7) + 1 = 50$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['50']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "h(x) = x^2 - 3"}, {"type": "paragraph", "text": "Which table gives three values of $x$ and their corresponding values of $h(x)$ for the given function $h$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$h(1) = 1 - 3 = -2$, $h(2) = 4 - 3 = 1$, and $h(3) = 9 - 3 = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 270(0.1)^x$. What is the value of $f(0)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Any nonzero number to the power $0$ is $1$, so $f(0) = 270 \\cdot 1 = 270$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "To estimate the proportion of a population that has a certain characteristic, a random sample was selected from the population. Based on the sample, it is estimated that the proportion of the population that has the characteristic is $0.49$, with an associated margin of error of $0.04$. Based on this estimate and margin of error, which of the following is the most appropriate conclusion about the proportion of the population that has the characteristic?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The plausible values are the estimate plus or minus the margin of error: $0.49 \\pm 0.04$, from $0.45$ to $0.53$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A moving truck can tow a trailer if the combined weight of the trailer and the boxes it contains is no more than $4{,}600$ pounds. What is the maximum number of boxes this truck can tow in a trailer with a weight of $500$ pounds if each box weighs $120$ pounds?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$500 + 120n \\le 4{,}600$ gives $120n \\le 4{,}100$, so $n \\le 34.1\\ldots$. The greatest whole number of boxes is $34$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "-4x^2 - 7x = -36"}, {"type": "paragraph", "text": "What is the positive solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Rearrange to $4x^2 + 7x - 36 = 0$ and factor: $(4x - 9)(x + 4) = 0$. The positive solution is $x = \\tfrac{9}{4}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m2-q13.png", "alt": "Figure for question 13", "width": 254}, {"type": "paragraph", "text": "The table summarizes the distribution of color and shape for $100$ tiles of equal area."}, {"type": "paragraph", "text": "If one of these tiles is selected at random, what is the probability of selecting a red tile? (Express your answer as a decimal or fraction, not as a percent.)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$30$ of the $100$ tiles are red, so the probability is $\\tfrac{30}{100} = 0.3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 13, 'spr', array['.3', '3/10']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 2x + 3"}, {"type": "paragraph", "text": "For the given function $f$, the graph of $y = f(x)$ in the $xy$-plane is parallel to line $j$. What is the slope of line $j$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Parallel lines have equal slopes. The slope of $y = 2x + 3$ is $2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 14, 'spr', array['2']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A proposal for a new library was included on an election ballot. A radio show stated that $3$ times as many people voted in favor of the proposal as people who voted against it. A social media post reported that $15{,}000$ more people voted in favor of the proposal than voted against it. Based on these data, how many people voted against the proposal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "If $a$ people voted against, then $3a$ voted in favor and $3a - a = 15{,}000$, so $a = 7{,}500$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m2-q16.png", "alt": "Figure for question 16", "width": 244}, {"type": "paragraph", "text": "In the figure, lines $m$ and $n$ are parallel. If $x = 6k + 13$ and $y = 8k - 29$, what is the value of $z$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Angles $x$ and $y$ are vertical angles, so $6k + 13 = 8k - 29$, giving $k = 21$ and $x = 139$. Angles $x$ and $z$ are same-side angles between the parallel lines, so $z = 180 - 139 = 41$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "-3x + 21px = 84"}, {"type": "paragraph", "text": "In the given equation, $p$ is a constant. The equation has no solution. What is the value of $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor: $x(21p - 3) = 84$. There is no solution only when the coefficient of $x$ is $0$: $21p = 3$, so $p = \\tfrac{1}{7}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = (x - 10)(x + 13)"}, {"type": "paragraph", "text": "The function $f$ is defined by the given equation. For what value of $x$ does $f(x)$ reach its minimum?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The zeros are $10$ and $-13$. The parabola opens upward, so its minimum is halfway between the zeros: $x = \\dfrac{10 + (-13)}{2} = -\\dfrac{3}{2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f(x) = \\dfrac{1}{9}(x - 7)^2 + 3$ gives a metal ball''s height above the ground $f(x)$, in inches, $x$ seconds after it started moving on a track, where $0 \\le x \\le 10$. Which of the following is the best interpretation of the vertex of the graph of $y = f(x)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The vertex is $(7, 3)$, and since the parabola opens upward it is the lowest point: the ball''s minimum height was $3$ inches, reached at $7$ seconds."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangle $JKL$, $\\cos(K) = \\dfrac{24}{51}$ and angle $J$ is a right angle. What is the value of $\\cos(L)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$K$ and $L$ are complementary, so $\\cos(L) = \\sin(K)$. With adjacent side $24$ and hypotenuse $51$, the opposite side is $\\sqrt{51^2 - 24^2} = 45$, so $\\cos(L) = \\tfrac{45}{51} = \\tfrac{15}{17}$ (about $0.8824$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 20, 'spr', array['15/17', '.8824', '.8823']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "-x^2 + bx - 676 = 0"}, {"type": "paragraph", "text": "In the given equation, $b$ is a positive integer. The equation has no real solution. What is the greatest possible value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "No real solution means the discriminant is negative: $b^2 - 4(-1)(-676) < 0$, so $b^2 < 2{,}704$ and $b < 52$. The greatest integer is $51$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 21, 'spr', array['51']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m2-q22.png", "alt": "Figure for question 22", "width": 267}, {"type": "paragraph", "text": "If a new graph of three linear equations is created using the system of equations shown and the equation $x + 4y = -16$, how many solutions $(x, y)$ will the resulting system of three equations have?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The slanted line passes through $(-4, 5)$ and $(8, 2)$, so it is $x + 4y = 16$. The line $x + 4y = -16$ is parallel to it and never meets it, so no point lies on all three lines: zero solutions."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 5{,}470(0.64)^{\\frac{x}{12}}"}, {"type": "paragraph", "text": "The function $f$ gives the value, in dollars, of a certain piece of equipment after $x$ months of use. If the value of the equipment decreases each **year** by $p\\%$ of its value the preceding year, what is the value of $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Every $12$ months the exponent increases by $1$, so each year the value is multiplied by $0.64$: a decrease of $1 - 0.64 = 0.36$, or $36\\%$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-04/math-m2-q24.png", "alt": "Figure for question 24", "width": 128}, {"type": "paragraph", "text": "The dot plot represents the $15$ values in data set A. Data set B is created by adding $56$ to each of the values in data set A. Which of the following correctly compares the medians and the ranges of data sets A and B?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Adding $56$ to every value shifts the median up by $56$, but the distance between the largest and smallest values does not change, so the range stays the same."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The equation $x^2 + (y - 1)^2 = 49$ represents circle A. Circle B is obtained by shifting circle A down $2$ units in the $xy$-plane. Which of the following equations represents circle B?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Circle A''s center is $(0, 1)$. Moving down $2$ units puts the center at $(0, -1)$, with the same radius: $x^2 + (y + 1)^2 = 49$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Two identical rectangular prisms each have a height of $90$ centimeters (cm). The base of each prism is a square, and the surface area of each prism is $K$ cm$^2$. If the prisms are glued together along a square base, the resulting prism has a surface area of $\\dfrac{92}{47}K$ cm$^2$. What is the side length, in cm, of each square base?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "With base side $s$: $K = 2s^2 + 360s$, and the glued prism (height $180$) has area $2s^2 + 720s$. So $47(2s^2 + 720s) = 92(2s^2 + 360s)$, which simplifies to $90s^2 = 720s$, giving $s = 8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "$210$ is $p\\%$ greater than $30$. What is the value of $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$210 = 30\\left(1 + \\dfrac{p}{100}\\right)$, so $1 + \\dfrac{p}{100} = 7$ and $p = 600$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 27, 'spr', array['600']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;
